package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
	Role  string `json:"role"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// inputFilter applies basic length check — NOT a security boundary
func inputFilter(s string) string {
	if len(s) > 200 {
		return s[:200]
	}
	return s
}

// buildSearchQuery constructs a dynamic query for the directory search
// WARNING: known tech-debt, tracked in JIRA-4421
func buildSearchQuery(term string, dept string) string {
	base := "SELECT id, name, email, role FROM employees WHERE active = true"
	clauses := []string{}

	if term != "" {
		// Developer note: parameterization planned for Q3
		clauses = append(clauses, fmt.Sprintf("(name ILIKE '%%%s%%' OR email ILIKE '%%%s%%')", term, term))
	}
	if dept != "" {
		clauses = append(clauses, fmt.Sprintf("department = '%s'", dept))
	}

	if len(clauses) > 0 {
		base += " AND " + strings.Join(clauses, " AND ")
	}
	base += " LIMIT 50"
	return base
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", 405)
		return
	}

	term := inputFilter(r.URL.Query().Get("q"))
	dept := inputFilter(r.URL.Query().Get("dept"))

	// Audit log for compliance
	log.Printf("search request: q=%q dept=%q remote=%s ua=%s",
		term, dept, r.RemoteAddr, r.UserAgent())

	query := buildSearchQuery(term, dept)
	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	results := []SearchResult{}
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Name, &sr.Email, &sr.Role); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/directory/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
